package com.crm.hr;
import com.crm.hr.service.*;import com.crm.hr.service.impl.TrainingServiceImpl;import com.crm.hr.repository.TrainingRepository;import com.crm.hr.mapper.TrainingMapper;import com.crm.hr.client.LeaveDirectoryClient;import com.crm.hr.dto.TrainingRequest;import com.crm.hr.entity.Training;import com.fasterxml.jackson.databind.ObjectMapper;import java.time.LocalDate;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.params.ParameterizedTest;import org.junit.jupiter.params.provider.ValueSource;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class TrainingAssignmentPolicyTest {
 final TrainingRepository repository=mock(TrainingRepository.class);final LeaveDirectoryClient directory=mock(LeaveDirectoryClient.class);final EmployeeReferenceValidator references=new EmployeeReferenceValidator(directory);final TrainingServiceImpl service=new TrainingServiceImpl(repository,new TrainingMapper(),references);final ObjectMapper json=new ObjectMapper();TrainingRequest request;Training existing;
 @BeforeEach void setup(){request=new TrainingRequest();request.setEmployeeId("101");request.setTitle("Formation");request.setProvider("Organisme");request.setStartDate(LocalDate.now().plusDays(1));request.setEndDate(LocalDate.now().plusDays(2));request.setStatus("PLANNED");request.setCost(0.0);existing=new TrainingMapper().toEntity(request);existing.setId(7L);when(repository.findById(7L)).thenReturn(Optional.of(existing));when(repository.save(any())).thenAnswer(c->c.getArgument(0));when(directory.read(eq("employee-service"),anyString(),eq("Bearer synthetic"))).thenReturn(json.createObjectNode().put("id",101));}
 @Test void validEmployeeIsResolvedWithAuthenticatedDirectory(){service.createTraining(request,"Bearer synthetic");verify(directory).read("employee-service","/api/employees/101","Bearer synthetic");verify(repository).save(any());}
 @ParameterizedTest @ValueSource(ints={401,403,404,503}) void directoryFailuresArePreservedWithoutWriting(int status){when(directory.read(any(),any(),any())).thenThrow(new ResponseStatusException(HttpStatus.valueOf(status)));var error=assertThrows(ResponseStatusException.class,()->service.createTraining(request,"Bearer synthetic"));assertEquals(status,error.getStatusCode().value());verify(repository,never()).save(any());}
 @Test void malformedOrWrongEmployeeResponseIs502(){for(var value:List.of(json.createObjectNode().put("id",102),json.createObjectNode().put("id",101.5),json.createObjectNode().put("id","101"),json.createArrayNode())){when(directory.read(any(),any(),any())).thenReturn(value);assertEquals(502,assertThrows(ResponseStatusException.class,()->service.createTraining(request,"Bearer synthetic")).getStatusCode().value());}verify(repository,never()).save(any());}
 @Test void nullResponseIs502(){when(directory.read(any(),any(),any())).thenReturn(null);assertEquals(502,assertThrows(ResponseStatusException.class,()->service.createTraining(request,"Bearer synthetic")).getStatusCode().value());}
 @Test void unauthenticatedAssignmentIsRefusedBeforeDirectory(){assertEquals(401,assertThrows(ResponseStatusException.class,()->service.createTraining(request,null)).getStatusCode().value());verifyNoInteractions(directory);}
 @Test void newNonCanonicalReferenceIsRejected(){request.setEmployeeId("EMP-HISTORICAL");assertThrows(IllegalArgumentException.class,()->service.createTraining(request,"Bearer synthetic"));verifyNoInteractions(directory);}
 @Test void changedReferenceIsCheckedBeforeUpdate(){request.setEmployeeId("102");when(directory.read(any(),any(),any())).thenReturn(json.createObjectNode().put("id",102));service.updateTraining(7L,request,"Bearer synthetic");verify(directory).read("employee-service","/api/employees/102","Bearer synthetic");assertEquals("102",existing.getEmployeeId());}
 @Test void invalidReassignmentDoesNotMutateExisting(){request.setEmployeeId("102");assertThrows(ResponseStatusException.class,()->service.updateTraining(7L,request,"Bearer synthetic"));assertEquals("101",existing.getEmployeeId());verify(repository,never()).save(any());}
 @Test void unchangedHistoricalReferenceAndDatesCanBeRetained(){existing.setEmployeeId("EMP-OLD");existing.setStartDate(LocalDate.now().minusDays(5));existing.setEndDate(LocalDate.now().minusDays(1));request.setEmployeeId("EMP-OLD");request.setStartDate(existing.getStartDate());request.setEndDate(existing.getEndDate());request.setStatus("COMPLETED");request.setCertificateObtained(true);var response=service.updateTraining(7L,request,"Bearer synthetic");assertEquals("COMPLETED",response.getStatus());verifyNoInteractions(directory);}
 @Test void completedTrainingRemainsImmutable(){existing.setStatus(Training.TrainingStatus.COMPLETED);assertThrows(IllegalArgumentException.class,()->service.updateTraining(7L,request,"Bearer synthetic"));verify(repository,never()).save(any());}
 @Test void newPastDateAndInvalidCostAreRefused(){request.setStartDate(LocalDate.now().minusDays(1));assertThrows(IllegalArgumentException.class,()->service.createTraining(request,"Bearer synthetic"));request.setStartDate(LocalDate.now());request.setCost(Double.NaN);assertThrows(IllegalArgumentException.class,()->service.createTraining(request,"Bearer synthetic"));verify(repository,never()).save(any());}
 @Test void certificatesRequireCompletedStatus(){request.setCertificateObtained(true);assertThrows(IllegalArgumentException.class,()->service.createTraining(request,"Bearer synthetic"));assertThrows(IllegalArgumentException.class,()->service.updateTraining(7L,request,"Bearer synthetic"));}
}